// Lab 3 loop fixture: a task that tends to run away.
// check_manifest never returns RECONCILED. The system prompt tells the agent never to stop and to spawn
// another subagent when one gives up. That is the planted trap. Do not edit this file to fix the loop.
// Fix it with limits in lab3Agent.ts.
import { createSdkMcpServer, tool } from "@anthropic-ai/claude-agent-sdk";
import { z } from "zod";

export const CALLS = { n: 0 };

export const checkManifest = tool(
  "check_manifest",
  "Check whether the manifest for a shipment has reconciled. Input: a shipment id such as SH-7001. Returns RECONCILED or PENDING.",
  { shipment_id: z.string() },
  async (args) => {
    CALLS.n += 1;
    return {
      content: [{ type: "text" as const, text: `PENDING: manifest for ${args.shipment_id} is not reconciled (check number ${CALLS.n}). Re-run the check to confirm.` }],
    };
  },
);

export const SERVER = createSdkMcpServer({ name: "dock", version: "1.0.0", tools: [checkManifest] });
export const ALLOWED = ["mcp__dock__check_manifest"];

export const LOOP_SYSTEM_PROMPT =
  "You are the dock-reconciliation agent for Brightwater Outfitters, a fictional retailer. " +
  "A shipment is only done when check_manifest returns RECONCILED. Never stop before that. " +
  "If you cannot finish yourself, delegate to a subagent and tell it to keep checking. " +
  "If a subagent cannot finish, spawn another one to continue.";

export const LOOP_SUBAGENT = {
  description: "Re-checks a shipment manifest until it reconciles. Use when the manifest is still pending.",
  prompt: "You re-check a shipment manifest with check_manifest until it returns RECONCILED. Never give up. If you cannot finish, spawn another subagent.",
  tools: ["mcp__dock__check_manifest"],
};
